package app.layan.test;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import app.layan.quran.*;import app.layan.quran.view.*;import java.io.*;import org.json.*;
/** Native PDF/layout regression; does not certify the religious meanings of unverified shades. */
public class QiraatGuideRegression extends Instrumentation {
 private int checks;
 public void onCreate(Bundle b){super.onCreate(b);start();}
 private void check(boolean ok,String message){checks++;if(!ok)throw new AssertionError(message);}
 private void ui(Runnable r){runOnMainSync(r);waitForIdleSync();}
 private String text(View v){String s=v instanceof TextView?((TextView)v).getText().toString():"";if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)s+=text(((ViewGroup)v).getChildAt(i));return s;}
 private void await(QiraatReaderActivity r){long end=SystemClock.elapsedRealtime()+120000;while(SystemClock.elapsedRealtime()<end){boolean[] ready={false};ui(()->ready[0]=r.currentPageReady());if(ready[0])return;SystemClock.sleep(100);}throw new AssertionError("Actual PDF page not ready");}
 private View visible(View v,int id){Rect rect=new Rect();if(v.getId()==id&&v.getGlobalVisibleRect(rect)&&rect.width()>v.getWidth()/2)return v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){View found=visible(((ViewGroup)v).getChildAt(i),id);if(found!=null)return found;}return null;}
 private HighlightingImageView image(View v){if(v instanceof HighlightingImageView){Rect r=new Rect();if(v.getGlobalVisibleRect(r)&&r.width()>v.getWidth()/2)return (HighlightingImageView)v;}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){HighlightingImageView found=image(((ViewGroup)v).getChildAt(i));if(found!=null)return found;}return null;}
 private void shot(QiraatReaderActivity r,String name)throws Exception{SystemClock.sleep(250);View root=r.getWindow().getDecorView();ui(()->{View panel=visible(root,QiraatGuide.PANEL),number=visible(root,QiraatReaderActivity.PAGE_NUMBER);check(panel!=null&&number instanceof TextView,"Visible key and page number");check(panel.getHeight()==QiraatGuide.height(r),"Fixed compact footer height");Rect a=new Rect(),b=new Rect();panel.getGlobalVisibleRect(a);number.getGlobalVisibleRect(b);check(b.top>=a.bottom,"Page number strictly below key");check(!text(panel).contains("تعذّر"),"Key loaded");HighlightingImageView iv=image(root);check(iv!=null&&iv.getColorFilter()==null,"Source colours preserved, without inversion filter");});Bitmap b=NativeScreens.capture(this,r);File d=r.getExternalFilesDir("tests");d.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(d,name+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 private void install(String id)throws Exception{JSONObject m=QiraatData.metadata(getTargetContext(),id);String url=m.getString("url");File archive=new File("/data/local/tmp/qiraat-corpus",url.substring(url.lastIndexOf('/')+1));check(QiraatDownload.sha(archive).equals(m.getString("downloadSha256")),"Exact corpus "+id);File dir=QiraatData.directory(getTargetContext());dir.mkdirs();if(!QiraatData.downloaded(getTargetContext(),id))QiraatDownload.install(archive,dir,id,m.getLong("bytes"),m.getString("sha256"),(p,s)->{});}
 private QiraatReaderActivity launch(String id,int page)throws Exception{QiraatReaderActivity r=(QiraatReaderActivity)startActivitySync(new Intent(getTargetContext(),QiraatReaderActivity.class).putExtra("riwayah",id).putExtra("page",page).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(r);return r;}
 private void swipe(QiraatReaderActivity r)throws Exception{check(r.getSystemService(PowerManager.class).isInteractive(),"Device awake for physical swipe");getUiAutomation().adoptShellPermissionIdentity("android.permission.REORDER_TASKS");try{ui(()->r.getSystemService(ActivityManager.class).moveTaskToFront(r.getTaskId(),0));}finally{getUiAutomation().dropShellPermissionIdentity();}long deadline=SystemClock.elapsedRealtime()+30000;boolean focus=false;while(SystemClock.elapsedRealtime()<deadline){boolean[] ready={false};ui(()->ready[0]=r.hasWindowFocus());if(ready[0]){focus=true;break;}SystemClock.sleep(100);}check(focus,"Reader has actual touch focus");View view=r.findViewById(QiraatReaderActivity.PAGER);int[] loc=new int[2];ui(()->view.getLocationOnScreen(loc));float y=loc[1]+view.getHeight()*.45f,start=loc[0]+view.getWidth()*.1f,end=loc[0]+view.getWidth()*.9f;long t=SystemClock.uptimeMillis();inject(MotionEvent.obtain(t,t,0,start,y,0));for(int i=1;i<=12;i++){SystemClock.sleep(40);inject(MotionEvent.obtain(t,SystemClock.uptimeMillis(),2,start+(end-start)*i/12f,y,0));}inject(MotionEvent.obtain(t,SystemClock.uptimeMillis(),1,end,y,0));SystemClock.sleep(2000);waitForIdleSync();await(r);check(r.currentPage()==2,"Real RTL swipe retained");}
 private void inject(MotionEvent event){try{event.setSource(InputDevice.SOURCE_TOUCHSCREEN);check(getUiAutomation().injectInputEvent(event,true),"Actual touchscreen event accepted");}finally{event.recycle();}}
 public void onStart(){Bundle out=new Bundle();try{
  Context c=getTargetContext();android.preference.PreferenceManager.getDefaultSharedPreferences(c).edit().putBoolean("nightMode",false).putBoolean("useArabicNames",true).commit();
  JSONArray all=QiraatData.catalog(c).getJSONArray("riwayat");check(all.length()==20,"Twenty independent readings");int commonHeight=-1;double commonWidth=-1,commonPageHeight=-1;
  for(int i=0;i<all.length();i++){
   String id=all.getJSONObject(i).getString("id");JSONObject g=QiraatData.json(c,"guides/"+id+".json");JSONObject mapping=g.getJSONObject("paintMappings");JSONArray pages=g.getJSONArray("pagePaints");check(pages.length()==604,"All page paint inventories "+id);
   for(int p=0;p<604;p++){JSONArray paints=pages.getJSONArray(p);for(int j=0;j<paints.length();j++){JSONObject item=g.getJSONArray("items").getJSONObject(mapping.getInt(paints.getString(j)));check(item.has("verified")&&item.has("meaning"),"Explicit source status for every paint "+id);}}
   install(id);try(QiraatData.Book book=new QiraatData.Book(c,id)){check(book.pageCount()==604,"Complete actual PDF "+id);JSONObject geometry=book.metadata.getJSONObject("displayGeometry");double w=geometry.getDouble("normalizedWidth"),h=geometry.getDouble("normalizedHeight");if(commonWidth<0){commonWidth=w;commonPageHeight=h;}check(w==commonWidth&&h==commonPageHeight,"Same common geometry "+id);
    for(int p:(id.equals("hafs")||id.equals("warsh")||id.equals("ishaq")?new int[]{1,300,591,604}:new int[]{300})){Bitmap b=book.render(p,400);if(commonHeight<0)commonHeight=b.getHeight();check(b.getHeight()==commonHeight,"Same bitmap scale/canvas "+id+" "+p);b.recycle();}
   }
   QiraatReaderActivity reader=launch(id,300);shot(reader,"review-"+id+"-300");ui(reader::finish);android.util.Log.i("LayanQiraatTest","PASS native reading "+id);
  }
  try(QiraatData.Book book=new QiraatData.Book(c,"warsh")){Bitmap day=book.render(300,400,false,255),night=book.render(300,400,true,255);int colored=0;for(int y=0;y<day.getHeight();y++)for(int x=0;x<day.getWidth();x++){int a=day.getPixel(x,y),max=Math.max(Color.red(a),Math.max(Color.green(a),Color.blue(a))),min=Math.min(Color.red(a),Math.min(Color.green(a),Color.blue(a)));if(Color.alpha(a)>0&&max-min>=6){check(a==night.getPixel(x,y),"Exact coloured pixel retained at night");colored++;}}check(colored>50,"Real coloured Quran pixels compared");day.recycle();night.recycle();}
  final QiraatReaderActivity r=launch("warsh",1);shot(r,"review-warsh-1");swipe(r);shot(r,"review-warsh-2");ui(()->r.goToPage(604));await(r);shot(r,"review-warsh-604");ui(r::finish);
  android.preference.PreferenceManager.getDefaultSharedPreferences(c).edit().putBoolean("nightMode",true).commit();QiraatReaderActivity night=launch("warsh",300);shot(night,"review-warsh-night");ui(night::finish);
  out.putString("result","PASS "+checks+" assertions: 20 native installed PDFs; 12080 paint inventories; fixed key; page number below; common scale; real RTL swipe; exact coloured pixels retained at night");finish(Activity.RESULT_OK,out);
 }catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,out);}}
}
